/* CMS controls for direct WhatsApp requests and search access. */
(()=>{
 if(!document.getElementById('app')||window.__rentcamCommerceInstalled)return;window.__rentcamCommerceInstalled=true;
 const cfg=()=>window.RENTCAM_CMS_CONFIG||{},esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const phone=v=>{let n=String(v||'').replace(/\D/g,'');return n.startsWith('0')?'62'+n.slice(1):n.startsWith('8')?'62'+n:n};
 let draft={},selectedDates=[];
 const money=n=>'Rp'+Number(n||0).toLocaleString('id-ID');
 function products(){try{return Array.isArray(P)?P:[]}catch(_){return []}}
 function items(){let cart=[];try{cart=JSON.parse(localStorage.getItem('bsm_cart_cm')||'[]')}catch(_){}return (Array.isArray(cart)?cart:[]).map(i=>({p:products().find(p=>String(p.id)===String(i.id)),q:Math.floor(Number(i.q))})).filter(i=>i.p&&i.p.active!==false&&i.p.deleted!==true&&i.q>0);}
 function mount(){
  const c=cfg(),off=c.commerce?.checkoutEnabled===false,tracking=c.commerce?.trackingEnabled!==false;
  document.documentElement.dataset.checkoutMode=off?'whatsapp':'full';document.documentElement.dataset.orderTracking=tracking?'on':'off';
  const host=document.querySelector('#app .summary');let quick=document.getElementById('rcQuickOrder');
  if(location.pathname==='/cart'&&host&&off&&items().length){
   if(!quick){host.insertAdjacentHTML('beforeend',`<form id="rcQuickOrder" class="rc-quick-order"><div class="rc-quick-heading"><span>RESERVASI RENTAL</span><h2>Kirim ke marketing</h2><p>Lengkapi periode sewa. Marketing akan mengonfirmasi stok dan harga melalui WhatsApp.</p></div><label>Nama lengkap<input name="name" autocomplete="name" required minlength="2" maxlength="100" placeholder="Nama Anda"></label><label>Pilihan tanggal<select name="dateMode"><option value="range">Rentang tanggal berurutan</option><option value="separate">Tanggal terpisah</option></select></label><div class="rc-quick-dates"><label>Tanggal sewa<input name="start" type="date" required></label><label>Tanggal selesai<input name="end" type="date" required></label></div><label class="rc-separate-dates" hidden>Pilih tanggal sewa<input name="pickDate" type="date"><button type="button" data-add-rental-date>Tambah tanggal</button><span data-rental-dates></span></label><p class="rc-rental-rule">Sewa minimal 3 hari berurutan: potongan 1 hari. Tanggal tidak berurutan tidak mendapat potongan. Potongan satu kali per periode.</p><label>Program / kebutuhan <span>(opsional)</span><input name="program" maxlength="200" placeholder="Film, iklan, event, atau kebutuhan lainnya"></label><div class="rc-quick-estimate" aria-live="polite"></div><p class="rc-quick-error" role="alert" hidden></p><button type="submit" class="wide">Kirim pesanan ke WhatsApp <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 17 17 7M7 7h10v10"/></svg></button><small>Pesanan dikonfirmasi setelah Anda mengirim pesan di WhatsApp.</small></form>`);quick=document.getElementById('rcQuickOrder');const today=new Date().toLocaleDateString('sv-SE');quick.elements.start.min=today;quick.elements.end.min=today;quick.elements.start.value=today;quick.elements.end.value=today;for(const [key,value] of Object.entries(draft))if(quick.elements[key])quick.elements[key].value=value;quick.addEventListener('input',()=>{draft=Object.fromEntries(['name','start','end','program','dateMode'].map(k=>[k,quick.elements[k].value]));estimate()});quick.addEventListener('click',e=>{if(e.target.closest('[data-add-rental-date]')){const v=quick.elements.pickDate.value;if(v&&!selectedDates.includes(v)&&v>=today)selectedDates.push(v);estimate()}const remove=e.target.closest('[data-remove-rental-date]');if(remove){selectedDates=selectedDates.filter(x=>x!==remove.dataset.removeRentalDate);estimate()}});quick.elements.pickDate.min=today;quick.addEventListener('submit',send);estimate();}
  }else quick?.remove();
  const app=document.getElementById('app'),note=document.getElementById('rcTrackingDisabled');
  if(!tracking&&location.pathname==='/cek-order'){if(!note)app.insertAdjacentHTML('beforeend','<section id="rcTrackingDisabled" class="container rc-tracking-disabled"><h1>Cek order sedang dinonaktifkan</h1><p>Hubungi marketing melalui WhatsApp untuk menanyakan pesanan Anda.</p><a class="btn" href="/produk">Lihat katalog</a></section>');}else note?.remove();
  if(location.pathname==='/cart'){cartTable();const title=document.querySelector('#app h1'),heading=host?.querySelector(':scope > h3');if(title?.textContent==='Rental Cart')title.textContent='Keranjang Sewa';if(heading?.textContent==='Summary')heading.textContent='Ringkasan Sewa';estimate()}
  dock();
 }
 function cartTable(){
  const layout=document.querySelector('#app .cartLayout'),list=layout?.firstElementChild;if(!list)return;
  for(const child of layout.children){child.style.setProperty('grid-column','1 / -1','important');child.style.setProperty('grid-row','auto','important');child.style.setProperty('max-width','none','important');child.style.setProperty('width','100%','important');child.style.setProperty('box-sizing','border-box','important')}
  if(list.querySelector('.rc-cart-table'))return;
  layout.style.setProperty('grid-template-columns','minmax(0,1fr)','important');layout.style.setProperty('display','grid','important');
  const cards=[...list.querySelectorAll('.cartItem')];if(!cards.length)return;
  const table=document.createElement('table');table.className='rc-cart-table';table.innerHTML='<caption>Daftar peralatan sewa</caption><thead><tr><th scope="col">Produk</th><th scope="col">Harga / hari</th><th scope="col">Jumlah</th><th scope="col">Subtotal / hari</th></tr></thead><tbody></tbody>';
  const selected=items();cards.forEach((card,n)=>{const controls=card.lastElementChild,id=controls?.querySelector('[onclick]')?.getAttribute('onclick')?.match(/upd\(['"]([^'"]+)/)?.[1],item=selected.find(i=>String(i.p.id)===id)||selected[n];if(!item)return;
   const tr=document.createElement('tr'),product=document.createElement('td'),rate=document.createElement('td'),qty=document.createElement('td'),subtotal=document.createElement('td');const content=document.createElement('div');content.className='rc-cart-product';const img=card.querySelector('img'),info=img?.nextElementSibling;if(img){img.alt=item.p.name;content.append(img)}if(info){const oldPrice=info.lastElementChild;if(oldPrice&&oldPrice.tagName==='DIV'&&oldPrice!==info.firstElementChild)oldPrice.remove();content.append(info)}product.append(content);rate.textContent=money(item.p.price);qty.className='rc-cart-qty';if(controls){controls.querySelectorAll('button').forEach(b=>{if(b.textContent.trim()==='Remove')b.textContent='Hapus';else b.setAttribute('aria-label',(b.textContent.trim()==='+'?'Tambah':'Kurangi')+' jumlah '+item.p.name)});qty.append(controls)}subtotal.textContent=money(Number(item.p.price)*item.q);tr.append(product,rate,qty,subtotal);table.tBodies[0].append(tr);card.remove();});
  const wrap=document.createElement('div');wrap.className='rc-cart-table-scroll';wrap.tabIndex=0;wrap.setAttribute('aria-label','Daftar produk, geser untuk melihat semua kolom');wrap.append(table);list.append(wrap);
 }
 function quotation(f){const dates=f.elements.dateMode.value==='separate'?selectedDates:RentcamRentalPricing.dates(f.elements.start.value,f.elements.end.value);return RentcamRentalPricing.quote(items(),dates,cfg().tax||{});}
 function estimate(){const f=document.getElementById('rcQuickOrder');if(!f)return;const separate=f.elements.dateMode.value==='separate';f.querySelector('.rc-quick-dates').hidden=separate;f.querySelector('.rc-separate-dates').hidden=!separate;f.elements.start.required=f.elements.end.required=!separate;f.elements.end.min=f.elements.start.value||f.elements.start.min;const chips=f.querySelector('[data-rental-dates]');const chipHtml=selectedDates.slice().sort().map(d=>`<button type="button" data-remove-rental-date="${esc(d)}" aria-label="Hapus tanggal ${esc(d)}">${esc(d)} ×</button>`).join('');if(chips.innerHTML!==chipHtml)chips.innerHTML=chipHtml;
 const q=quotation(f),t=cfg().tax||{},row=(a,b)=>`<div class="rc-cost-row"><span>${a}</span><strong>${b}</strong></div>`;const html='<h3>Rincian biaya sewa</h3>'+row('Durasi',q.days+' hari · bayar '+q.paidDays+' hari')+'<div class="rc-cost-table-scroll"><table class="rc-cost-table"><thead><tr><th>Produk</th><th>Jumlah</th><th>Hari</th><th>Biaya</th></tr></thead><tbody>'+q.rows.map(r=>'<tr><td>'+esc(r.name)+'<small>'+money(r.price)+' / hari</small></td><td>'+r.quantity+'</td><td>'+q.days+'</td><td>'+money(r.gross)+'</td></tr>').join('')+'</tbody></table></div>'+row('Subtotal sebelum diskon',money(q.gross))+row('Diskon '+q.freeDays+' hari',q.discount?'−'+money(q.discount):money(0))+(q.days&&!q.consecutive?'<small>Tanggal tidak berurutan: tanpa diskon.</small>':'')+row('Subtotal setelah diskon',money(q.subtotal))+(t.enabled===true?row(esc(t.label||'PPN')+' ('+Number(t.rate||0)+'%)',money(q.tax)):'')+'<div class="rc-cost-total">'+row('Total estimasi',money(q.total))+'</div>';const el=f.querySelector('.rc-quick-estimate');if(el.innerHTML!==html)el.innerHTML=html;
 }
 function send(e){e.preventDefault();const f=e.currentTarget,error=f.querySelector('.rc-quick-error'),fail=m=>{error.hidden=false;error.textContent=m};if(!f.reportValidity())return;const name=f.elements.name.value.trim();if(name.length<2)return fail('Isi nama lengkap Anda.');const q=quotation(f),today=new Date().toLocaleDateString('sv-SE');if(!q.days||q.dates.some(d=>d<today))return fail('Pilih tanggal sewa yang valid, mulai hari ini.');const target=phone(cfg().general?.marketingWhatsapp||cfg().general?.whatsapp);if(!/^62[0-9]{7,14}$/.test(target))return fail('Nomor WhatsApp marketing belum tersedia. Hubungi admin.');if(!q.rows.length)return fail('Keranjang kosong. Pilih produk terlebih dahulu.');const t=cfg().tax||{};
 const lines=['*PERMINTAAN SEWA — '+(cfg().general?.siteName||'Rental Kamera')+'*','','*Data pelanggan*','Nama: '+name,'Tanggal sewa: '+q.dates.join(', '),'Durasi: '+q.days+' hari','Hari berbayar: '+q.paidDays+' hari',...(f.elements.program.value.trim()?['Program: '+f.elements.program.value.trim()]:[]),'','*Rincian peralatan*',...q.rows.flatMap((r,n)=>[(n+1)+'. '+r.name,'   '+r.quantity+' unit × '+money(r.price)+' × '+q.days+' hari = '+money(r.gross),'   Potongan: '+money(r.discount)+' · Subtotal: '+money(r.total)]),'','Subtotal sebelum diskon: '+money(q.gross),'Diskon '+q.freeDays+' hari: '+money(q.discount),...(!q.consecutive?['Tanggal tidak berurutan: tanpa diskon.']:[]),'Subtotal setelah diskon: '+money(q.subtotal),...(t.enabled===true?[(t.label||'PPN')+': '+money(q.tax)]:[]),'*Total estimasi: '+money(q.total)+'*','','Mohon konfirmasi ketersediaan alat dan total biaya.'];error.hidden=true;window.open('https://wa.me/'+target+'?text='+encodeURIComponent(lines.join('\n')),'_blank','noopener');
 }
 const search=document.createElement('form');search.className='rc-search-dock';search.setAttribute('role','search');search.setAttribute('aria-label','Pencarian produk');search.hidden=true;search.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/></svg><input type="search" aria-label="Cari produk" placeholder="Cari produk…"><button type="submit">Cari</button>';document.body.append(search);
 function original(){return document.querySelector('#productSearchInput,.rc-camera-search input')}
 function dock(){const actions=document.querySelector('.header .actions'),menu=actions?.querySelector('[data-menu]');if(actions&&search.parentElement!==actions)actions.insertBefore(search,menu||actions.firstChild);search.hidden=!actions;search.classList.add('rc-header-search');search.style.setProperty('display',actions?'flex':'none','important');}
 search.addEventListener('submit',e=>{e.preventDefault();const q=search.querySelector('input').value.trim();if(typeof go==='function')go('/produk'+(q?'?q='+encodeURIComponent(q):''));else location.href='/produk?q='+encodeURIComponent(q);});
 search.querySelector('input').addEventListener('input',e=>{const input=original();if(input?.id==='productSearchInput'){input.value=e.target.value;window.rentcamLiveSearch?.({target:input})}});
 let pending=false;const schedule=()=>{if(pending)return;pending=true;requestAnimationFrame(()=>{pending=false;mount()})};new MutationObserver(schedule).observe(document.getElementById('app'),{childList:true,subtree:true});document.addEventListener('rentcam-cms-updated',schedule);document.addEventListener('rentcam-route-change',schedule);addEventListener('scroll',dock,{passive:true});addEventListener('resize',dock);mount();
})();
